namespace Ordering;

/// <summary>Coordinates product-return operations through focused services.</summary>
public sealed class ReturnsHandler
{
    private readonly ProcessedReturnRegistry _processedReturns = new();
    private readonly RestockLedger _restockLedger = new();
    private readonly RefundCalculator _refundCalculator = new();
    private readonly RefundJournal _refundJournal = new();

    public string ProcessReturn(Order order, Customer customer)
    {
        var service = new ReturnAcceptanceService(_processedReturns, _restockLedger);
        return service.Process(order, customer);
    }

    public bool IsReturnable(Order order)
    {
        var policy = new ReturnEligibilityPolicy(_processedReturns);
        return policy.IsReturnable(order);
    }

    public decimal ComputeRefund(Order order) =>
        _refundCalculator.Compute(order, _refundJournal.Count);

    public void LogRefund(Order order, decimal amount) =>
        _refundJournal.Log(order, amount);

    public int Restock(Order order) => _restockLedger.Restock(order);
}

internal sealed class ReturnAcceptanceService
{
    private readonly ProcessedReturnRegistry _processedReturns;
    private readonly RestockLedger _restockLedger;

    public ReturnAcceptanceService(
        ProcessedReturnRegistry processedReturns,
        RestockLedger restockLedger)
    {
        _processedReturns = processedReturns;
        _restockLedger = restockLedger;
    }

    public string Process(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedReturns.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _restockLedger.AddPending(line.Sku, line.Quantity);
        }

        if (_restockLedger.IsEmpty)
            return "no returnable lines";

        _processedReturns.Add(order.Reference);
        return "accepted";
    }
}

internal sealed class ReturnEligibilityPolicy
{
    private readonly ProcessedReturnRegistry _processedReturns;

    public ReturnEligibilityPolicy(ProcessedReturnRegistry processedReturns)
    {
        _processedReturns = processedReturns;
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedReturns.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity >= 1 &&
                line.Quantity <= 100 &&
                !string.IsNullOrEmpty(line.Sku))
            {
                return true;
            }
        }

        return false;
    }
}

internal sealed class ProcessedReturnRegistry
{
    private readonly HashSet<string> _references = new(StringComparer.Ordinal);

    public bool Contains(string reference) => _references.Contains(reference);

    public void Add(string reference) => _references.Add(reference);
}

internal sealed class RestockLedger
{
    private readonly Dictionary<string, int> _pendingBySku = new(StringComparer.Ordinal);

    public bool IsEmpty => _pendingBySku.Count == 0;

    public void AddPending(string sku, int quantity)
    {
        _pendingBySku[sku] = _pendingBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;

            if (_pendingBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _pendingBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _pendingBySku[sku] = line.Quantity / 2;
            }
            else
            {
                _pendingBySku[sku] = line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }
}

internal sealed class RefundCalculator
{
    private const decimal UnitRefund = 5m;

    public decimal Compute(Order order, int loggedRefundCount)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else
                refund += line.Quantity * UnitRefund;
        }

        if (loggedRefundCount > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }
}

internal sealed class RefundJournal
{
    private readonly List<string> _entries = new();

    public int Count => _entries.Count;

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;

        if (_entries.Count == 0 || amount > 100m)
            _entries.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _entries.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _entries.Add($"{order.Reference}:mid:{amount}");
        else
            _entries.Add($"{order.Reference}:small:{amount}");

        if (_entries.Count > 500 && amount > 1000m)
            _entries.Add($"{order.Reference}:flag");
    }
}
